import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.DLWhSH9p.js";const p=JSON.parse('{"title":"Buyer & Seller","description":"","frontmatter":{},"headers":[],"relativePath":"guide/auth.md","filePath":"guide/auth.md"}'),s={name:"guide/auth.md"};function l(i,e,n,u,h,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="buyer-seller" tabindex="-1">Buyer &amp; Seller <a class="header-anchor" href="#buyer-seller" aria-label="Permalink to &quot;Buyer &amp; Seller&quot;">​</a></h1><p>Every account on Mossworks has two sides — <strong>Buyer</strong> and <strong>Seller</strong> — and you can switch between them whenever you like. Most people start as a Buyer, build a channel, and add Seller later.</p><h2 id="buyer" tabindex="-1">Buyer <a class="header-anchor" href="#buyer" aria-label="Permalink to &quot;Buyer&quot;">​</a></h2><p>The default. As a Buyer you can:</p><ul><li>Create channels, write scripts, produce audio, render episodes, and publish.</li><li>Browse the Marketplace and <strong>hire</strong> sellers (voice actors, editors, animators, musicians).</li><li><strong>Post gigs</strong> so sellers can apply with a quote.</li></ul><h2 id="seller" tabindex="-1">Seller <a class="header-anchor" href="#seller" aria-label="Permalink to &quot;Seller&quot;">​</a></h2><p>Sellers offer their craft on the Marketplace. As a Seller you can:</p><ul><li>Build a profile, list demos and packages, set availability and rates.</li><li>Apply to posted gigs or get hired directly from your profile.</li><li>Get paid through Stripe — sellers pay zero platform fees.</li></ul><p>See the <a href="/guide/marketplace.html">Marketplace guide</a> for the full Seller flow, including the onboarding checklist.</p><h2 id="switching-personas" tabindex="-1">Switching personas <a class="header-anchor" href="#switching-personas" aria-label="Permalink to &quot;Switching personas&quot;">​</a></h2><p>Open the <strong>Profile</strong> menu at the bottom of the sidebar and toggle between <strong>Buyer</strong> and <strong>Seller</strong>. The sidebar reshapes to surface the tools that matter for the side you&#39;re on; your data and signed-in identity stay the same.</p><h2 id="sign-out" tabindex="-1">Sign out <a class="header-anchor" href="#sign-out" aria-label="Permalink to &quot;Sign out&quot;">​</a></h2><p>Open the <strong>Profile</strong> menu and click <strong>Sign out</strong> at the bottom. This ends your session and returns you to the login screen.</p>',13)])])}const g=a(s,[["render",l]]);export{p as __pageData,g as default};
